19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
23	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	};
28	
29	const quotePremium = (step: QuoteStep): number => {
30	  const itemPremiums = step.items.map(
31	    (item) => BASE_PREMIUMS[item.type] * (1 + FIRST_INSURANCE_SURCHARGE),
32	  );
33	  const total = itemPremiums.reduce((sum, premium) => sum + premium, 0);
34	
35	  return roundUp(total + PROCESSING_FEE);
36	};
37	
38	export const runScenario = (scenario: Scenario): ScenarioResults => ({
39	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
40	});
