const itemPremium = (item: Item): number =>
  BASE_PREMIUMS[item.type] * (1 + FIRST_INSURANCE_SURCHARGE);

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + itemPremium(item),
    0,
  );

  return roundUp(policyBasePremium + PROCESSING_FEE);
};
